with valid as (select id, product_name, category, price, cost, stock_qty, tags, supplier_id, substring(product_name, 1, 4) product_name_prefix, coalesce(brand, 'DIRECT') brand_filled from products where brand is null) select id, product_name, category, price, supplier_id, product_name_prefix, last_value(cost) ignore nulls over (partition by category order by stock_qty, id rows between unbounded preceding and current row) last_known_cost, sum(stock_qty) over (partition by supplier_id order by cost, id rows between unbounded preceding and current row) running_stock_qty from valid;
